INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (17, 'M17.7', 'Exam Question Bank', 7)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'High speed propellers are designed to', '[{"id": "a", "text": "rotate at high RPM.", "correct": false}, {"id": "b", "text": "operate at high forward speeds.", "correct": true}, {"id": "c", "text": "operate at supersonic tip speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When in the windmill position ATM', '[{"id": "a", "text": "opposes CTM.", "correct": false}, {"id": "b", "text": "is not related to CTM.", "correct": false}, {"id": "c", "text": "assists CTM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A left handed propeller is one that', '[{"id": "a", "text": "rotates clockwise when viewed from the rear.", "correct": false}, {"id": "b", "text": "rotates clockwise when viewed from the front.", "correct": true}, {"id": "c", "text": "is fitted to an engine on the left side of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Forces acting on a propeller are', '[{"id": "a", "text": "centrifugal, twisting, and bending.", "correct": true}, {"id": "b", "text": "torque, thrust and centrifugal.", "correct": false}, {"id": "c", "text": "torsion, tension and thrust.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The blade angle at the root is', '[{"id": "a", "text": "less than the tip.", "correct": false}, {"id": "b", "text": "same from tip to root.", "correct": false}, {"id": "c", "text": "greater than the tip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What force on a propeller blade turns the blades to a fine pitch?', '[{"id": "a", "text": "ATM.", "correct": false}, {"id": "b", "text": "Torque.", "correct": false}, {"id": "c", "text": "CTM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of propeller twist is', '[{"id": "a", "text": "coarsen the blade angle at the root.", "correct": false}, {"id": "b", "text": "to maintain Blade Angle along the blade.", "correct": false}, {"id": "c", "text": "to maintain Angle of Attack at the same value along the blade.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The forces acting on a propeller blade are', '[{"id": "a", "text": "bending, twisting and centrifugal.", "correct": true}, {"id": "b", "text": "thrust, aerodynamic and tension.", "correct": false}, {"id": "c", "text": "thrust and torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade angle at the root is', '[{"id": "a", "text": "low.", "correct": false}, {"id": "b", "text": "high.", "correct": true}, {"id": "c", "text": "master blade angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade angle is taken from the chord and', '[{"id": "a", "text": "propeller shaft.", "correct": false}, {"id": "b", "text": "relative airflow.", "correct": false}, {"id": "c", "text": "plane of rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What forces act on a propeller blade?', '[{"id": "a", "text": "Thrust and torque.", "correct": false}, {"id": "b", "text": "Bending, thrust, torque.", "correct": false}, {"id": "c", "text": "Bending, CTM and ATM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'CTM will', '[{"id": "a", "text": "try to bend the blade away from the engine.", "correct": false}, {"id": "b", "text": "turn the blade about the lateral axis.", "correct": true}, {"id": "c", "text": "cause the tips to rotate at supersonic speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'From reverse pitch, to return to normal pitch it', '[{"id": "a", "text": "passes throughh coarse then fine.", "correct": false}, {"id": "b", "text": "passes throughh coarse.", "correct": false}, {"id": "c", "text": "passes throughh fine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When in reverse pitch, CTM will tend to move the propeller blades towards', '[{"id": "a", "text": "a positive pitch.", "correct": false}, {"id": "b", "text": "a position depending on rpm.", "correct": false}, {"id": "c", "text": "a negative pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the blade angle is increased', '[{"id": "a", "text": "the pitch becomes finer.", "correct": false}, {"id": "b", "text": "the pitch becomes coarser.", "correct": true}, {"id": "c", "text": "lateral stability decreases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A rotating propeller imparts rearwards motion to a', '[{"id": "a", "text": "small mass of air at high velocity.", "correct": false}, {"id": "b", "text": "large mass of air at low velocity.", "correct": true}, {"id": "c", "text": "small mass of air at low velocity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller efficiency is', '[{"id": "a", "text": "the ratio of output speed to input propeller speed.", "correct": false}, {"id": "b", "text": "the ratio of the work applied to the geometric pitch to useful work on the C.S.U.", "correct": false}, {"id": "c", "text": "the ratio of the useful work done by the propeller to work done by the engine on the", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Geometric Pitch is the distance moved', '[{"id": "a", "text": "in one revolution without slip.", "correct": true}, {"id": "b", "text": "in one revolution with slip.", "correct": false}, {"id": "c", "text": "in one revolution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'As propeller rotation speed increases the centrifugal turning moment on the blades will', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "remain constant throughh r.p.m. range.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller torque is the resistance offered by the propeller to', '[{"id": "a", "text": "feathering.", "correct": false}, {"id": "b", "text": "changing pitch.", "correct": false}, {"id": "c", "text": "rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The angle between the resultant airflow direction and the propeller blade plane of rotation is known as', '[{"id": "a", "text": "angle of attack.", "correct": false}, {"id": "b", "text": "blade angle.", "correct": false}, {"id": "c", "text": "helix angle or angle of advance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Coarse pitch is used for', '[{"id": "a", "text": "take off and climb.", "correct": false}, {"id": "b", "text": "maximum economical cruise in level flight.", "correct": true}, {"id": "c", "text": "landing and power checks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Effective pitch is', '[{"id": "a", "text": "distance moved in one revolution.", "correct": true}, {"id": "b", "text": "geometric pitch plus slip.", "correct": false}, {"id": "c", "text": "pitch measured at the master station.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A windmilling Propeller has', '[{"id": "a", "text": "a small positive blade angle.", "correct": false}, {"id": "b", "text": "a small positive angle of attack.", "correct": false}, {"id": "c", "text": "a small negative angle of attack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Windmilling causes', '[{"id": "a", "text": "propeller underspeeding.", "correct": false}, {"id": "b", "text": "maximum propeller drag.", "correct": true}, {"id": "c", "text": "centrifugal Twisting Moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Torque acts', '[{"id": "a", "text": "in the same direction as the plane of rotation.", "correct": false}, {"id": "b", "text": "at right angles to the plane of rotation.", "correct": false}, {"id": "c", "text": "in opposition to the direction of rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of blade twist is to', '[{"id": "a", "text": "reduce angle of attack at the blade root.", "correct": false}, {"id": "b", "text": "to ensure that tip speed does not go faster than Mach 1.", "correct": false}, {"id": "c", "text": "to even out thrust distribution across the propeller.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Thrust is greatest', '[{"id": "a", "text": "at 70 to 80% of propeller length.", "correct": true}, {"id": "b", "text": "in the first 50%.", "correct": false}, {"id": "c", "text": "the same all along the length.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'CTM changes the pitch of a blade', '[{"id": "a", "text": "about its twisting axis.", "correct": true}, {"id": "b", "text": "bending forward.", "correct": false}, {"id": "c", "text": "towards the feather plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The velocity of the slipstream behind the aircraft in relation to the ambient air is', '[{"id": "a", "text": "less.", "correct": false}, {"id": "b", "text": "greater.", "correct": true}, {"id": "c", "text": "equal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'High speed aerofoils are employed at', '[{"id": "a", "text": "the master station.", "correct": false}, {"id": "b", "text": "the tips.", "correct": true}, {"id": "c", "text": "the root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A right hand propeller', '[{"id": "a", "text": "rotates clockwise when viewed from the rear.", "correct": true}, {"id": "b", "text": "is always fitted to the starboard engine.", "correct": false}, {"id": "c", "text": "rotates clockwise when viewed from the front.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Given that blade angle is measured from the centre of the hub, the blade angle at the hub is considered to be', '[{"id": "a", "text": "lowest.", "correct": false}, {"id": "b", "text": "Master Station value.", "correct": false}, {"id": "c", "text": "highest.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A windmilling propeller will create', '[{"id": "a", "text": "more drag in feather.", "correct": false}, {"id": "b", "text": "more drag in fine pitch.", "correct": true}, {"id": "c", "text": "more drag in coarse pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The chord line of a propeller is', '[{"id": "a", "text": "a line joining the leading and trailing edges.", "correct": true}, {"id": "b", "text": "a line joining the tip to the root of the blade.", "correct": false}, {"id": "c", "text": "a line joining the tips of the blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The plane of rotation is defined as', '[{"id": "a", "text": "the plane in which thrust force acts.", "correct": false}, {"id": "b", "text": "the plane in which the propeller rotates.", "correct": true}, {"id": "c", "text": "the angle at which the blade strikes the airflow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Thrust bending force on a propeller blade', '[{"id": "a", "text": "intensifies the centrifugal forces to some degrees.", "correct": false}, {"id": "b", "text": "can be used in propeller design to reduce some operation stress.", "correct": false}, {"id": "c", "text": "tends to bend the propeller blade forward at the tip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What conditions are applied to a propeller blade windmilling?', '[{"id": "a", "text": "Positive angle of attack, thrust negative.", "correct": false}, {"id": "b", "text": "Negative angle of attack, thrust positive.", "correct": false}, {"id": "c", "text": "Negative angle of attack, thrust negative.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The primary purpose of propeller is to', '[{"id": "a", "text": "change engine horsepower to thrust.", "correct": true}, {"id": "b", "text": "provide static and dynamic stability to aircraft.", "correct": false}, {"id": "c", "text": "create lift on the fixed aerofoils of an aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The primary purpose of a feathering propeller is to', '[{"id": "a", "text": "prevent further engine damage when an engine fails in flight.", "correct": false}, {"id": "b", "text": "prevent propeller damage when an engine fails in flight.", "correct": false}, {"id": "c", "text": "eliminate the drag created by a windmilling propeller when an engine fails in flight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A fibreglass composite blade', '[{"id": "a", "text": "will never be struck by lighting.", "correct": false}, {"id": "b", "text": "does not require lightning strike protection.", "correct": false}, {"id": "c", "text": "requires lightning strike protection.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The timber most often used today for propeller construction is', '[{"id": "a", "text": "birch.", "correct": false}, {"id": "b", "text": "spruce.", "correct": true}, {"id": "c", "text": "balsa.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Electronic torque measuring systems utilise', '[{"id": "a", "text": "strain gauges in the reduction gear.", "correct": true}, {"id": "b", "text": "stress gauges in the reduction gear.", "correct": false}, {"id": "c", "text": "pressure transducers in the reduction gear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A conventional turboprop torque meter uses', '[{"id": "a", "text": "hydraulic oil as the pressure medium.", "correct": false}, {"id": "b", "text": "coiled spring levers as the pressure medium.", "correct": false}, {"id": "c", "text": "engine oil as the pressure medium.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Metal at the tip and along the leading edge of a wooden propeller is for', '[{"id": "a", "text": "balancing.", "correct": false}, {"id": "b", "text": "protection.", "correct": true}, {"id": "c", "text": "anti-icing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade cuffs are fitted to the root of the blades', '[{"id": "a", "text": "to increase the strength of the blade.", "correct": false}, {"id": "b", "text": "to increase thrust.", "correct": false}, {"id": "c", "text": "to increase flow of cooling air into the engine nacelle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Low torque sensing is used to', '[{"id": "a", "text": "increase power.", "correct": false}, {"id": "b", "text": "increase pitch.", "correct": false}, {"id": "c", "text": "initiate auto-feather.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Torque sensing is used to', '[{"id": "a", "text": "reduce drag.", "correct": false}, {"id": "b", "text": "reduce drag following engine shutdown.", "correct": true}, {"id": "c", "text": "synchronise blade angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The thrust of a propeller is normally taken by the', '[{"id": "a", "text": "torque meter.", "correct": false}, {"id": "b", "text": "propeller rear cone.", "correct": false}, {"id": "c", "text": "front bearing in the reduction gear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On which type of turbo-propeller would you expect to find a parking brake?', '[{"id": "a", "text": "Compounded twin spool.", "correct": false}, {"id": "b", "text": "Direct coupled twin spool.", "correct": false}, {"id": "c", "text": "Free turbine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What does the torquemeter reading indicate in a gas turbine engine?', '[{"id": "a", "text": "Torque reaction at the reduction gear.", "correct": true}, {"id": "b", "text": "The ratio between engine thrust and engine torque.", "correct": false}, {"id": "c", "text": "Engine torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The gear segments on the blade roots of a hydromatic propeller mesh with the', '[{"id": "a", "text": "stationary cam.", "correct": false}, {"id": "b", "text": "torque tubes and eye bolts.", "correct": false}, {"id": "c", "text": "moving cam.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller is centralised on the propeller shaft by', '[{"id": "a", "text": "the front and rear cones.", "correct": true}, {"id": "b", "text": "the front git seal.", "correct": false}, {"id": "c", "text": "the rear pre-load shims.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Reduction gearing allows the blade tips', '[{"id": "a", "text": "to operate below the speed of sound.", "correct": true}, {"id": "b", "text": "to operate above the speed of sound.", "correct": false}, {"id": "c", "text": "to rotate slower than the root of the propeller blade.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What is the purpose of small holes at the tip of wooden propellers?', '[{"id": "a", "text": "Drainage.", "correct": true}, {"id": "b", "text": "Balancing.", "correct": false}, {"id": "c", "text": "Pivot points used during manufacture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The thrust face of a propeller blade is the', '[{"id": "a", "text": "root to which the gear segment is fitted.", "correct": false}, {"id": "b", "text": "blade face or flat side.", "correct": true}, {"id": "c", "text": "blade back or curved side.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Solidity of a propeller can be increased by increasing', '[{"id": "a", "text": "blade chord.", "correct": true}, {"id": "b", "text": "blade angle.", "correct": false}, {"id": "c", "text": "blade thickness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Total power of a turbo-prop engine is measured in', '[{"id": "a", "text": "Equivalent Shaft Horsepower (ESHP).", "correct": true}, {"id": "b", "text": "Shaft Horsepower (SHP).", "correct": false}, {"id": "c", "text": "Brake Horsepower (BHP).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The disadvantage of using reverse pitch on a turbo-propeller engine is', '[{"id": "a", "text": "exhaust gas ingestion , high gas temperature and debris ingestion.", "correct": true}, {"id": "b", "text": "debris ingestion.", "correct": false}, {"id": "c", "text": "high gas temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A compound twin spool engine is', '[{"id": "a", "text": "turbo prop propeller driven by a power turbine.", "correct": false}, {"id": "b", "text": "turbo prop twin spool compressor.", "correct": true}, {"id": "c", "text": "LP Compressor driven by a free turbine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When the power lever on a turbo prop engine is moved from ground idle to flight fine the fuel flow', '[{"id": "a", "text": "increases.", "correct": true}, {"id": "b", "text": "decreases.", "correct": false}, {"id": "c", "text": "remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How is the blade station measured?', '[{"id": "a", "text": "In inches from the centre of the hub.", "correct": true}, {"id": "b", "text": "In inches from the tip.", "correct": false}, {"id": "c", "text": "As a percentage of blade length from the tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The oil used in the torquemeter system is', '[{"id": "a", "text": "DTD 5 8 5.", "correct": false}, {"id": "b", "text": "engine oil pressure boosted by a pump driven off the reduction gear.", "correct": true}, {"id": "c", "text": "PCU oil pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade stations are measured from the', '[{"id": "a", "text": "centre of the hub.", "correct": true}, {"id": "b", "text": "tip.", "correct": false}, {"id": "c", "text": "shank.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Auto feathering is disarmed', '[{"id": "a", "text": "during landing.", "correct": false}, {"id": "b", "text": "during take off.", "correct": false}, {"id": "c", "text": "in the cruise.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'With a multi-engined aircraft the torque pressure would be', '[{"id": "a", "text": "There is only one gauge for all engines.", "correct": false}, {"id": "b", "text": "same on all engines.", "correct": false}, {"id": "c", "text": "similar on all engines.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If torque pressure fell to zero during the cruise what would indicate that the gauge had failed?', '[{"id": "a", "text": "Engine would auto feather.", "correct": false}, {"id": "b", "text": "Engine would overspeed.", "correct": false}, {"id": "c", "text": "Engine would continue to run.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of using reverse pitch propellers is to', '[{"id": "a", "text": "provide aerodynamic braking.", "correct": true}, {"id": "b", "text": "allow aircraft to taxi backwards.", "correct": false}, {"id": "c", "text": "reverse the direction of rotation of the propeller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The RPM of a windmilling propeller is primarily related to', '[{"id": "a", "text": "EAS.", "correct": false}, {"id": "b", "text": "IAS.", "correct": false}, {"id": "c", "text": "TAS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A ducted propeller is used because', '[{"id": "a", "text": "ducted props give more thrust for the diameter of disc.", "correct": true}, {"id": "b", "text": "only ducted propellers can be vectored.", "correct": false}, {"id": "c", "text": "ducted props give less thrust for the diameter of disc.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A two position prop uses', '[{"id": "a", "text": "high pitch for take off and low pitch for cruise.", "correct": false}, {"id": "b", "text": "low pitch for take off and climb and high pitch for cruise.", "correct": true}, {"id": "c", "text": "high pitch for take off, low pitch for climb and descent and high pitch for cruise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller operating in the Beta range is operating between', '[{"id": "a", "text": "Flight Idle and Ground Idle.", "correct": false}, {"id": "b", "text": "coarse and flight fine pitch.", "correct": false}, {"id": "c", "text": "maximum reverse pitch and Flight idle pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Counterweights are used to', '[{"id": "a", "text": "counter the ATM of the blades.", "correct": false}, {"id": "b", "text": "counteract the CTM of the blades.", "correct": true}, {"id": "c", "text": "balance the blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The pressure face of a propeller is', '[{"id": "a", "text": "the flat face.", "correct": true}, {"id": "b", "text": "the leading edge.", "correct": false}, {"id": "c", "text": "the camber face.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In blade station numbering the stations nearest the hub are', '[{"id": "a", "text": "datum.", "correct": false}, {"id": "b", "text": "highest.", "correct": false}, {"id": "c", "text": "lowest.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller mounted forward of the engine is known as', '[{"id": "a", "text": "hydromatic propeller.", "correct": false}, {"id": "b", "text": "a tractor propeller.", "correct": true}, {"id": "c", "text": "a pusher propeller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Contra-rotating propellers are', '[{"id": "a", "text": "two propellers on the same shaft on one engine-each revolving in a different direction.", "correct": true}, {"id": "b", "text": "propellers geared to rotate in the opposite direction to the engine.", "correct": false}, {"id": "c", "text": "propellers on a twin engined aircraft revolving in opposite directions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'An aerodynamic braking propeller goes throughh', '[{"id": "a", "text": "the feathered pitch position to act as a brake.", "correct": false}, {"id": "b", "text": "the coarse pitch position to act as a brake.", "correct": false}, {"id": "c", "text": "the fine pitch position to act as a brake.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The term spinner is applied to', '[{"id": "a", "text": "a propeller tip vortex.", "correct": false}, {"id": "b", "text": "a streamline covering over the propeller hub.", "correct": true}, {"id": "c", "text": "an acrobatic manoeuvre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Variable pitch propellers are used because they are', '[{"id": "a", "text": "reduce vibration and noise.", "correct": false}, {"id": "b", "text": "have peak efficiency over a greater speed range.", "correct": true}, {"id": "c", "text": "more economical.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The condition lever normally has the following settings', '[{"id": "a", "text": "normal, beta-range and reverse range.", "correct": false}, {"id": "b", "text": "cut-off, idle and high idle.", "correct": true}, {"id": "c", "text": "rich, lean and cut-off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In a variable pitch propeller system, a decrease in propeller RPM will alter the angle of attack on the blade to', '[{"id": "a", "text": "increase negative torque.", "correct": false}, {"id": "b", "text": "decrease angle of attack.", "correct": true}, {"id": "c", "text": "increase angle of attack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'To achieve reverse pitch the blade angle must be', '[{"id": "a", "text": "more than 17°.", "correct": false}, {"id": "b", "text": "less than 0°.", "correct": true}, {"id": "c", "text": "more than 90°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Centrifugal latches are fitted to lock the propeller', '[{"id": "a", "text": "in the feathered position.", "correct": false}, {"id": "b", "text": "when stationary.", "correct": false}, {"id": "c", "text": "in the fine pitch position.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Counterweights are fitted to blade root to', '[{"id": "a", "text": "counteract ATM.", "correct": false}, {"id": "b", "text": "assist blade to move to fine pitch.", "correct": false}, {"id": "c", "text": "counteract CTM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The range of angles of a VP propeller is usually limited by', '[{"id": "a", "text": "the fine pitch position.", "correct": false}, {"id": "b", "text": "the feathering angle.", "correct": false}, {"id": "c", "text": "coarse and fine pitch stops.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of fine pitch stop is to', '[{"id": "a", "text": "maintain constant speed in flight.", "correct": false}, {"id": "b", "text": "prevent the propeller moving below flight fine pitch in flight.", "correct": true}, {"id": "c", "text": "maintain maximum RPM at takeoff.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which best describes a Variable Pitch propeller?', '[{"id": "a", "text": "The blade angles can be changed in flight.", "correct": true}, {"id": "b", "text": "Its blade angles are set with an automatic system with which the pilot has no input.", "correct": false}, {"id": "c", "text": "Its blade angles can only be set on the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The holding coil of a hydromatic propeller feathering button switch holds a relay closed that applies', '[{"id": "a", "text": "dome feathering mechanism.", "correct": false}, {"id": "b", "text": "feathering pump motor.", "correct": true}, {"id": "c", "text": "governor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The primary purpose of the front and rear cones for propellers that are installed on splined shafts is to', '[{"id": "a", "text": "prevent metal-to-metal contact between the propeller and the splined shaft.", "correct": false}, {"id": "b", "text": "reduce stresses between the splines of the propeller and the splines of the shaft.", "correct": false}, {"id": "c", "text": "position the propeller hub on the splined shaft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The constant-speed control unit is also called a', '[{"id": "a", "text": "propeller pitch control.", "correct": false}, {"id": "b", "text": "accumulator.", "correct": false}, {"id": "c", "text": "governor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When the compressive force on a speeder spring is reduced, the propeller blades will', '[{"id": "a", "text": "remain fixed.", "correct": false}, {"id": "b", "text": "fine off.", "correct": false}, {"id": "c", "text": "coarsen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When in the beta range, the propeller pitch is controlled', '[{"id": "a", "text": "directly from the power lever.", "correct": true}, {"id": "b", "text": "indirectly from the power lever.", "correct": false}, {"id": "c", "text": "directly from the pitch change mechanism to the PCU.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the speeder spring pressure of a CSU is increased the blade will', '[{"id": "a", "text": "coarsen off.", "correct": false}, {"id": "b", "text": "fine off.", "correct": true}, {"id": "c", "text": "will not move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On an underspeed condition the blades are turned to', '[{"id": "a", "text": "fine.", "correct": true}, {"id": "b", "text": "feather.", "correct": false}, {"id": "c", "text": "coarse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In a hydromatic propeller with counterweights, what is used to make the propeller move to fine pitch?', '[{"id": "a", "text": "A T M.", "correct": false}, {"id": "b", "text": "engine oil.", "correct": true}, {"id": "c", "text": "centrifugal force acting on the counterweight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Relaxing tension on the governor spring will result in the blade coarsening and', '[{"id": "a", "text": "RPM decreasing, manifold pressure increasing.", "correct": true}, {"id": "b", "text": "RPM increasing, manifold pressure increasing.", "correct": false}, {"id": "c", "text": "manifold pressure constant, RPM decreasing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The ground fine pitch stop is', '[{"id": "a", "text": "never removed.", "correct": false}, {"id": "b", "text": "removed on the ground.", "correct": true}, {"id": "c", "text": "removed during flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If governor flywheel overcomes the speeder spring, it indicates', '[{"id": "a", "text": "underspeed.", "correct": false}, {"id": "b", "text": "overspeed.", "correct": true}, {"id": "c", "text": "onspeed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Pitch control using torque measuring is for', '[{"id": "a", "text": "reducing drag in engine failure.", "correct": true}, {"id": "b", "text": "increasing drag.", "correct": false}, {"id": "c", "text": "reducing drag in binding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If force is applied to the speeder spring by control lever, what will happen?', '[{"id": "a", "text": "Blade angle coarsen.", "correct": false}, {"id": "b", "text": "Blade angle is frozen in last known position.", "correct": false}, {"id": "c", "text": "Blade angle finer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When is superfine pitch used?', '[{"id": "a", "text": "Landing and takeoff.", "correct": false}, {"id": "b", "text": "In cruise.", "correct": false}, {"id": "c", "text": "Engine starting to reduce propeller torque loading on starter motor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When the flyweights fly outwards in a PCU, this is known as', '[{"id": "a", "text": "onspeed.", "correct": false}, {"id": "b", "text": "overspeed.", "correct": true}, {"id": "c", "text": "low power settings with higher than normal pitch setting for ground manoeuvres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On a reversing propeller moving to the maximum reversing angle, the propeller goes', '[{"id": "a", "text": "from fine pitch throughh plane of rotation, coarse reverse then fine reverse.", "correct": false}, {"id": "b", "text": "from coarse pitch throughh plane of rotation course, fine reverse then coarse reverse.", "correct": false}, {"id": "c", "text": "from fine pitch throughh plane of rotation, fine reverse then coarse reverse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If pressure is increased on the speeder spring, rpm increases. What happens to the blade angle?', '[{"id": "a", "text": "Remains unchanged.", "correct": false}, {"id": "b", "text": "Increases.", "correct": false}, {"id": "c", "text": "Decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In a prop with counterweights, what is used to make it move to fine pitch?', '[{"id": "a", "text": "ATM.", "correct": false}, {"id": "b", "text": "Centrifugal force acting on the counterweight.", "correct": false}, {"id": "c", "text": "Governor oil pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If a propeller is in fine pitch and then moves to feather it will pass through', '[{"id": "a", "text": "flight fine only.", "correct": false}, {"id": "b", "text": "reverse.", "correct": false}, {"id": "c", "text": "coarse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A "double" acting propeller has', '[{"id": "a", "text": "nitrogen or air on one side of piston.", "correct": false}, {"id": "b", "text": "oil pressure on one side of piston.", "correct": false}, {"id": "c", "text": "oil pressure on two sides of piston.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'During normal propeller operation, oil pressure for the governor is provided by', '[{"id": "a", "text": "a pump in the governor.", "correct": true}, {"id": "b", "text": "a variable volume pump.", "correct": false}, {"id": "c", "text": "the engine driven pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Oil for an on-speed condition passes throughh', '[{"id": "a", "text": "the coarse pitch line.", "correct": false}, {"id": "b", "text": "the fine pitch line.", "correct": false}, {"id": "c", "text": "neither of the lines.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the spur gear pump in a single acting propeller governor failed, the', '[{"id": "a", "text": "blades would turn to a coarse pitch.", "correct": true}, {"id": "b", "text": "blades would rotate to a fine pitch.", "correct": false}, {"id": "c", "text": "blades would move to the feather position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The hydromatic variable pitch propeller is operated on the principle of', '[{"id": "a", "text": "oil pressure moving a piston.", "correct": true}, {"id": "b", "text": "an electrical motor moving a gear segment.", "correct": false}, {"id": "c", "text": "a venturi or ''u'' tube with mercury.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The constant speed unit (C.S.U.) governor works on the principle of', '[{"id": "a", "text": "manual selection throughh a gearbox.", "correct": false}, {"id": "b", "text": "centrifugal twisting moments.", "correct": false}, {"id": "c", "text": "spring pressure acting against centrifugal force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of the pitch change cams is to', '[{"id": "a", "text": "convert rotary motion to linear motion.", "correct": false}, {"id": "b", "text": "prevent windmilling.", "correct": false}, {"id": "c", "text": "convert linear motion to rotary motion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The gear type pump in a C.S.U. or P.C.U', '[{"id": "a", "text": "lubricates the entire propeller system.", "correct": false}, {"id": "b", "text": "boosts engine oil system pressure.", "correct": true}, {"id": "c", "text": "assist the governor valve to move.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The purpose of an accumulator in a single acting propeller system is to', '[{"id": "a", "text": "accelerate the unfeathering process.", "correct": true}, {"id": "b", "text": "to port oil to the coarse pitch oil line to assist in feathering the propeller.", "correct": false}, {"id": "c", "text": "provide back up to the governor pump.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On a free turbine engine it is possible to vary the propeller RPM whilst the engine RPM remains constant', '[{"id": "a", "text": "by operating the PCU control Lever.", "correct": true}, {"id": "b", "text": "it is not possible to vary the propeller RPM.", "correct": false}, {"id": "c", "text": "by operating the Power lever.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller control unit hydraulic system is supplied with oil from the', '[{"id": "a", "text": "engine lubrication oil tank.", "correct": true}, {"id": "b", "text": "aircraft hydraulic System.", "correct": false}, {"id": "c", "text": "PCU oil tank.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Low torque sensing is used to initiate', '[{"id": "a", "text": "relighting.", "correct": false}, {"id": "b", "text": "fine pitch selection.", "correct": false}, {"id": "c", "text": "auto feathering.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What is the purpose of the auto coarsening system?', '[{"id": "a", "text": "To prevent overspeeding in the event of the flight fine pitch stop failing.", "correct": true}, {"id": "b", "text": "To reduce drag during power loss.", "correct": false}, {"id": "c", "text": "To save the pilot making minor changes when changing altitude.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In a single acting propeller, blade angle is increased by', '[{"id": "a", "text": "counterweights and a feathering spring.", "correct": true}, {"id": "b", "text": "CTM.", "correct": false}, {"id": "c", "text": "oil pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The minimum propeller pitch is established by the', '[{"id": "a", "text": "pitch lock.", "correct": false}, {"id": "b", "text": "superfine pitch stop.", "correct": true}, {"id": "c", "text": "flight fine pitch stop.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What are the centrifugal latches in a single acting propeller used for?', '[{"id": "a", "text": "Prevent CTM.", "correct": false}, {"id": "b", "text": "Prevent feathering of the prop on shutdown.", "correct": true}, {"id": "c", "text": "Prevent Propeller moving to superfine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'An overspeed condition causes governor spring pressure to be', '[{"id": "a", "text": "the same as centrifugal force.", "correct": false}, {"id": "b", "text": "more than centrifugal force.", "correct": false}, {"id": "c", "text": "less than centrifugal force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When the engine is running, the CSU is sensing', '[{"id": "a", "text": "propeller tip speed.", "correct": false}, {"id": "b", "text": "propeller blade angle.", "correct": false}, {"id": "c", "text": "engine RPM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'An accumulator may be fitted to', '[{"id": "a", "text": "feather the propeller.", "correct": false}, {"id": "b", "text": "unfeather the propeller.", "correct": true}, {"id": "c", "text": "provide emergency control.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If governor weight spring pressure is reduced', '[{"id": "a", "text": "governor weights will pivot inwards, raising the governor valve and allowing the blades to move to a", "correct": false}, {"id": "b", "text": "governor weights will spring outwards, raising the governor valve and allowing the blades to move to a", "correct": false}, {"id": "c", "text": "governor weights will spring outwards, raising the governor valve and allowing the blades", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A constant speed variable pitch propeller is running whilst stationary on the ground. If it is facing into a headwind it will', '[{"id": "a", "text": "slow down.", "correct": false}, {"id": "b", "text": "remain constant.", "correct": true}, {"id": "c", "text": "speed up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the TAS of an aircraft increases, the CSU will', '[{"id": "a", "text": "increase the blade angle to provide constant RPM.", "correct": true}, {"id": "b", "text": "decrease the blade angle to provide constant RPM.", "correct": false}, {"id": "c", "text": "change the blade angle to provide constant RPM.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When governor spring load is less than governor weights, the CSU is in', '[{"id": "a", "text": "underspeed.", "correct": false}, {"id": "b", "text": "overspeed.", "correct": true}, {"id": "c", "text": "normal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'An aircraft`s propeller system beta range.', '[{"id": "a", "text": "refers to the most fuel efficient pitch range to use at a given engine RPM.", "correct": false}, {"id": "b", "text": "is used to achieve maximum thrust during take-off.", "correct": false}, {"id": "c", "text": "is used to produce zero or negative thrust.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How is the oil pressure delivery on a hydromatic propeller normally stopped after the blades have reached their full-feathered position?', '[{"id": "a", "text": "Stop lugs in the teeth of the rotating cam.", "correct": false}, {"id": "b", "text": "Electric cut-out pressure switch.", "correct": true}, {"id": "c", "text": "Pulling out the feathering push-button.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Counterweights on constant-speed propellers are generally used to', '[{"id": "a", "text": "increase blade angle.", "correct": true}, {"id": "b", "text": "decrease blade angle.", "correct": false}, {"id": "c", "text": "unfeather the propeller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Constant speed non-feathering McCauley, Hartzell and other propellers of similar design without counterweights increase pitch angle using', '[{"id": "a", "text": "spring pressure.", "correct": false}, {"id": "b", "text": "centrifugal twisting moment.", "correct": false}, {"id": "c", "text": "oil pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What are the rotational speed and blade pitch angle requirements of a constant-speed propeller during take-off?', '[{"id": "a", "text": "High speed and low pitch angle.", "correct": true}, {"id": "b", "text": "High speed and high pitch angle.", "correct": false}, {"id": "c", "text": "Low speed and high pitch angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A constant speed propeller provides maximum efficiency by', '[{"id": "a", "text": "increasing the lift coefficient of the blades.", "correct": false}, {"id": "b", "text": "adjusting blade angle for most conditions encountered during flight.", "correct": true}, {"id": "c", "text": "increasing blade pitch as the aircraft speed increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Synchrophasing reduces vibration by the use of', '[{"id": "a", "text": "pulse probes and a single synchrophase unit.", "correct": true}, {"id": "b", "text": "tachometers and correction motors.", "correct": false}, {"id": "c", "text": "coordinating the rpm of each engine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Synchronising is carried out to', '[{"id": "a", "text": "match engine rpm.", "correct": false}, {"id": "b", "text": "match propeller tip speed.", "correct": true}, {"id": "c", "text": "match blade phase angle difference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The synchronisation governor monitors', '[{"id": "a", "text": "RPM.", "correct": true}, {"id": "b", "text": "propeller tip speeds.", "correct": false}, {"id": "c", "text": "thrust tip speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Synchronisation is used to', '[{"id": "a", "text": "reduce vibration and noise.", "correct": true}, {"id": "b", "text": "reduce the pitch of the fastest running blade.", "correct": false}, {"id": "c", "text": "preset the phase angle of propellers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Synchronisation is used', '[{"id": "a", "text": "on the ground.", "correct": false}, {"id": "b", "text": "in flight except landing and take off.", "correct": true}, {"id": "c", "text": "in flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The propeller synchronising system is put into operation by', '[{"id": "a", "text": "adjusting the engine rpm at required cruise speed then switching on the synchroniser.", "correct": true}, {"id": "b", "text": "adjusting the engine rpm then propeller rpm to required speed then switching on.", "correct": false}, {"id": "c", "text": "switching on the synchronizer then adjust the engine rpm so that all engines adjust together.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propellers are synchronised by the', '[{"id": "a", "text": "power lever.", "correct": false}, {"id": "b", "text": "PCU governor.", "correct": true}, {"id": "c", "text": "prop lever.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Unlike the automatic synchronizing system, the synchrophasing system of a two-propeller aircraft', '[{"id": "a", "text": "sets the blade phase angle of two constant speed propellers.", "correct": true}, {"id": "b", "text": "causes the same rotation speed of the two propellers.", "correct": false}, {"id": "c", "text": "matches the blade angle of variable pitch propellers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If one signal is lost into the comparator unit when synchrophasing is operating', '[{"id": "a", "text": "both engines remain running until their speeds differ by 4-5%, at which point the slower engine is", "correct": false}, {"id": "b", "text": "the slower engine immediately goes to feather.", "correct": false}, {"id": "c", "text": "synchrophasing is lost and the engines continue to function normally.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When should synchronisation be used?', '[{"id": "a", "text": "During cruise.", "correct": true}, {"id": "b", "text": "During landing.", "correct": false}, {"id": "c", "text": "Anytime.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller Synchronizing works utilizing', '[{"id": "a", "text": "RPM Levers.", "correct": false}, {"id": "b", "text": "propeller lever.", "correct": false}, {"id": "c", "text": "governor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller synchrophasing system allows a pilot to reduce noise and vibration by', '[{"id": "a", "text": "setting the RPM of all propellers exactly the same.", "correct": false}, {"id": "b", "text": "adjusting the plane of rotation of all propellers.", "correct": false}, {"id": "c", "text": "adjusting the phase angle between the propellers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller synchronising system allows a pilot to reduce noise and vibration by', '[{"id": "a", "text": "adjusting the phase angle between the propellers.", "correct": false}, {"id": "b", "text": "setting the RPM of all propellers exactly the same.", "correct": true}, {"id": "c", "text": "adjusting the plane of rotation of all propellers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What is the function of automatic propeller synchronizing system on multiengined aircraft?', '[{"id": "a", "text": "To control tip speed of all propellers.", "correct": false}, {"id": "b", "text": "To control the power output of all engines.", "correct": false}, {"id": "c", "text": "To control engine RPM and reduce vibration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On most reciprocating multiengined aircraft, automatic propeller synchronization is accomplished throughh the actuation of the', '[{"id": "a", "text": "propeller governors.", "correct": true}, {"id": "b", "text": "propeller control levers.", "correct": false}, {"id": "c", "text": "throttle levers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Electrically de-iced propeller slip rings have regular resistance checks for', '[{"id": "a", "text": "oxidisation due to altitude.", "correct": false}, {"id": "b", "text": "open circuit heating elements.", "correct": false}, {"id": "c", "text": "wear between brushes and slip ring.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller anti-icing may be achieved by', '[{"id": "a", "text": "using commercial de-icing fluid sprayed on the propeller.", "correct": false}, {"id": "b", "text": "using iso-propyl alcohol de-icing fluid sprayed on the blade.", "correct": true}, {"id": "c", "text": "a using hot air from the compressor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'De-icing of the propeller can be monitored by', '[{"id": "a", "text": "viewing the deicing fluid level sight glass.", "correct": false}, {"id": "b", "text": "viewing the blade and observing ice falling off the blade.", "correct": false}, {"id": "c", "text": "an ammeter in the flight deck.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Insulation checks on propeller electrical heating elements should be carried out frequently due to', '[{"id": "a", "text": "short/open circuits in the heating system wires along the propeller blade.", "correct": false}, {"id": "b", "text": "oxidation of slip ring and brush gear assembly.", "correct": false}, {"id": "c", "text": "deposits formed due to the wear of slip ring and brush gear assembly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Where is the de-icing boot?', '[{"id": "a", "text": "Root.", "correct": true}, {"id": "b", "text": "Trailing edge.", "correct": false}, {"id": "c", "text": "Tip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How is anti icing fluid fed to the individual blades?', '[{"id": "a", "text": "Pump to a slinger ring.", "correct": true}, {"id": "b", "text": "Pump to each blade rubber feed boot.", "correct": false}, {"id": "c", "text": "Under gravity to the slinger ring then on to the blade.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Ice is removed from blades by', '[{"id": "a", "text": "a continuously heated electrical boot.", "correct": false}, {"id": "b", "text": "rubber boots inflated in sequence using compressor hot air.", "correct": false}, {"id": "c", "text": "inboard and outboard boot sections heated in sequence by action of the timer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller blades are de-iced by', '[{"id": "a", "text": "electrical heating elements bound in rubber overshoes on the blade leading edges.", "correct": true}, {"id": "b", "text": "generating eddy currents in the blade.", "correct": false}, {"id": "c", "text": "electrical heating elements wound around rubber shoes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Electrical power supplies on large aircraft, for electrical deicing are', '[{"id": "a", "text": "AC.", "correct": false}, {"id": "b", "text": "DC.", "correct": false}, {"id": "c", "text": "Both AC or DC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller slip rings', '[{"id": "a", "text": "convey oil for PCU to pitch change mechanism.", "correct": false}, {"id": "b", "text": "minimise slip.", "correct": false}, {"id": "c", "text": "conduct electrical power for de-icing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On an electrical deicing system fast cycle is used', '[{"id": "a", "text": "at low air temperature.", "correct": false}, {"id": "b", "text": "at high air temperature.", "correct": true}, {"id": "c", "text": "on the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The output of an anti-icing pump is controlled by', '[{"id": "a", "text": "a rheostat.", "correct": true}, {"id": "b", "text": "the hand pump.", "correct": false}, {"id": "c", "text": "a cyclic timer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'De-icing fluid goes to a slinger ring from', '[{"id": "a", "text": "an electrical pump.", "correct": true}, {"id": "b", "text": "a hand pump.", "correct": false}, {"id": "c", "text": "a tank in the prop hub, providing constant feed once released.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller de-icing for varying rates of icing can be varied by', '[{"id": "a", "text": "increasing propeller RPM.", "correct": false}, {"id": "b", "text": "increasing cyclic timing.", "correct": true}, {"id": "c", "text": "increasing the AC or DC voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller De-icing can be checked by', '[{"id": "a", "text": "checking the the de-icing ammeter.", "correct": true}, {"id": "b", "text": "checking the torque meter for abnormal readings.", "correct": false}, {"id": "c", "text": "visually checking for ice on the blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Proper operation of electric deicing boots on individual propeller blades may be best determined by', '[{"id": "a", "text": "feeling the sequence of boot heating and have an assistant observe the loadmeter", "correct": true}, {"id": "b", "text": "feeling the boots to see if they are heating.", "correct": false}, {"id": "c", "text": "observing the ammeter or loadmeter for current flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What unit in the propeller anti-icing system controls the output of the pump?', '[{"id": "a", "text": "Pressure relief valve.", "correct": false}, {"id": "b", "text": "Rheostat.", "correct": true}, {"id": "c", "text": "Cycling timer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Ice formation on the propellers, when the aircraft is in flight, will', '[{"id": "a", "text": "decrease available engine power.", "correct": false}, {"id": "b", "text": "increase aircraft stall speed and increase noise.", "correct": false}, {"id": "c", "text": "decrease thrust and cause excessive vibration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller fluid anti-icing systems generally use which of the following?', '[{"id": "a", "text": "Ethyl alcohol.", "correct": false}, {"id": "b", "text": "Ethylene glycol.", "correct": false}, {"id": "c", "text": "Isopropyl alcohol.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'An aerodynamic correction factor that is preceded by the letter Q indicates', '[{"id": "a", "text": "thrust balance.", "correct": false}, {"id": "b", "text": "dynamic balance.", "correct": false}, {"id": "c", "text": "torque balance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the tip of an electrical overshoe is torn', '[{"id": "a", "text": "it may be cut back.", "correct": false}, {"id": "b", "text": "it may be classified as acceptable damage.", "correct": false}, {"id": "c", "text": "it must not be cut back.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The shank of the propeller is permitted to have', '[{"id": "a", "text": "no repairs.", "correct": true}, {"id": "b", "text": "minor repairs.", "correct": false}, {"id": "c", "text": "no decals fitted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Composite propellers may have minor repairs carried out by', '[{"id": "a", "text": "any approved 3rd party maintenance organization.", "correct": false}, {"id": "b", "text": "the operator.", "correct": false}, {"id": "c", "text": "any approved composite repair facility.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The ground clearance of a single engine tail wheel aircraft propeller is measured with the aircraft', '[{"id": "a", "text": "tail wheel on the ground.", "correct": false}, {"id": "b", "text": "tail wheel in the take off position.", "correct": true}, {"id": "c", "text": "in the rigging position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The structural clearance of a multi engine aircraft propeller', '[{"id": "a", "text": "is taken between the engines with the props aligned.", "correct": false}, {"id": "b", "text": "is taken between the prop and the fuselage.", "correct": true}, {"id": "c", "text": "is taken from the ground.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What position should the blades be when installing the pitch change mechanism onto a hydromatic propeller?', '[{"id": "a", "text": "Feather.", "correct": true}, {"id": "b", "text": "Zero pitch.", "correct": false}, {"id": "c", "text": "Full reverse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Dynamic balance is confirmed by use of', '[{"id": "a", "text": "knife edges and mandrel.", "correct": false}, {"id": "b", "text": "a tracking check.", "correct": false}, {"id": "c", "text": "a vibration analyser.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A metal propeller may be statically balanced by', '[{"id": "a", "text": "adding varnish to the lighter blade.", "correct": false}, {"id": "b", "text": "removing metal from the opposite blade.", "correct": false}, {"id": "c", "text": "adding or removing lead wool to the hollow blade roots.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Mechanical vibration relating to propellers in a piston powered aircraft', '[{"id": "a", "text": "is due to the crankshaft at intermittent power settings.", "correct": false}, {"id": "b", "text": "is due to the lead lag of the propeller compared to the engine.", "correct": false}, {"id": "c", "text": "is due to the power stroke of the engine and may have a more detrimental effect than", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Aerodynamic Correction Factor (A C F)', '[{"id": "a", "text": "corrects for static balance.", "correct": false}, {"id": "b", "text": "is indicated in the form of degrees and minutes of pitch.", "correct": true}, {"id": "c", "text": "corrects for dynamic balance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A propeller with an adjustable blade can be adjusted', '[{"id": "a", "text": "on the ground with the engine stationary.", "correct": true}, {"id": "b", "text": "in flight.", "correct": false}, {"id": "c", "text": "on the ground with the engine running.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Operation with the engine at maximum boost should be limited to', '[{"id": "a", "text": "prop at fine to prevent overstressing the engine.", "correct": false}, {"id": "b", "text": "prop at course to prevent overstressing the engine.", "correct": true}, {"id": "c", "text": "prop at windmill to prevent overstressing the engine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Damage to a leading edge can be blended in comparison to a blade face', '[{"id": "a", "text": "by maintaining a smooth depression.", "correct": false}, {"id": "b", "text": "by not exceeding 25% of the chord.", "correct": false}, {"id": "c", "text": "at a steeper angle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A tracking check compares', '[{"id": "a", "text": "2 Adjacent blades.", "correct": false}, {"id": "b", "text": "2 Opposite blades.", "correct": false}, {"id": "c", "text": "any 2 blades.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller vibration due to a problem with propeller installations would have a', '[{"id": "a", "text": "the same frequency as turbine vibration.", "correct": false}, {"id": "b", "text": "lower frequency than turbine vibration.", "correct": true}, {"id": "c", "text": "higher frequency than turbine vibration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Preloading propeller blades before installation prevents', '[{"id": "a", "text": "blade distortion.", "correct": false}, {"id": "b", "text": "blade flutter.", "correct": true}, {"id": "c", "text": "aerodynamic imbalance on the blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When unfeathering a propeller, the blade should be put into what position to stop propeller overspeed?', '[{"id": "a", "text": "Negative pitch.", "correct": false}, {"id": "b", "text": "Fine pitch.", "correct": false}, {"id": "c", "text": "Coarse pitch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade angle is measured using a', '[{"id": "a", "text": "clinometer.", "correct": false}, {"id": "b", "text": "propeller protractor.", "correct": true}, {"id": "c", "text": "bevel protractor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'With a propeller defect, the frequency of vibration will be', '[{"id": "a", "text": "higher than a auxiliary gearbox defect.", "correct": false}, {"id": "b", "text": "lower than a turbine defect.", "correct": true}, {"id": "c", "text": "higher than a turbine defect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blending of propeller blade defects refers to the', '[{"id": "a", "text": "repainting of blade tips after cropping.", "correct": false}, {"id": "b", "text": "matching of paint finishes for appearances.", "correct": false}, {"id": "c", "text": "conversion of rough or sharp edges into smooth depression.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Removal of material from the propeller blade tips, resulting in a reduction in propeller diameter is called', '[{"id": "a", "text": "tipping.", "correct": false}, {"id": "b", "text": "cropping.", "correct": true}, {"id": "c", "text": "topping.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Prior to using the universal propeller protractor', '[{"id": "a", "text": "ensure the propeller blade is at the horizontal.", "correct": false}, {"id": "b", "text": "determine the reference blade station.", "correct": true}, {"id": "c", "text": "check date stamp for serviceability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Blade tracking is adjusted by', '[{"id": "a", "text": "adding lead wool to the blade shank.", "correct": false}, {"id": "b", "text": "re-seating the propeller on the front and rear cones.", "correct": false}, {"id": "c", "text": "by fitting shims to the propeller shaft hub.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following functions requires the use of a propeller blade station?', '[{"id": "a", "text": "Indexing blades.", "correct": false}, {"id": "b", "text": "Propeller balancing.", "correct": false}, {"id": "c", "text": "Measuring blade angle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'To conduct a power check of an internal combustion engine requires', '[{"id": "a", "text": "coarse pitch setting and advance the throttle to the target RPM.", "correct": false}, {"id": "b", "text": "fine pitch setting and advance the engine to the target RPM setting.", "correct": true}, {"id": "c", "text": "fine pitch setting and advance the engine to the max RPM setting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The power output of a turboprop engine is checked by', '[{"id": "a", "text": "reference RPM.", "correct": false}, {"id": "b", "text": "reference Thrust.", "correct": false}, {"id": "c", "text": "reference Torque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Immediately after blending out damage to a blade the repair must be', '[{"id": "a", "text": "re-protected against corrosion.", "correct": false}, {"id": "b", "text": "crack checked.", "correct": true}, {"id": "c", "text": "balanced.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'After a lightning strike', '[{"id": "a", "text": "the prop must be tracked.", "correct": false}, {"id": "b", "text": "the propeller shaft should be checked for concentricity.", "correct": false}, {"id": "c", "text": "the heater elements should be checked for continuity and insulation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Indentations to the blade face are measured', '[{"id": "a", "text": "individually.", "correct": false}, {"id": "b", "text": "individually and collectively.", "correct": true}, {"id": "c", "text": "collectively.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When a propeller has had a report of overspeeding', '[{"id": "a", "text": "procedure is dependant on the extent of overspeeding.", "correct": true}, {"id": "b", "text": "the propeller must be removed and sent to the manufacturer.", "correct": false}, {"id": "c", "text": "the propeller must be removed and tracked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The most significant effect of stone chips on a propeller is', '[{"id": "a", "text": "thrust output of the propeller.", "correct": false}, {"id": "b", "text": "structural integrity of the propeller.", "correct": true}, {"id": "c", "text": "aerodynamic capability of the propeller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Ground running an aircraft with a fixed pitch prop with its tail into wind causes the engine RPM to', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "stay the same regardless of wind direction.", "correct": false}, {"id": "c", "text": "decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Adjustments to a variable pitch propeller are', '[{"id": "a", "text": "made in the air using the synchronizer.", "correct": false}, {"id": "b", "text": "made on the ground with the engine stationary.", "correct": true}, {"id": "c", "text": "made on the ground with the engine running.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'During engine warm up the mixture should be at', '[{"id": "a", "text": "rich, blades at feather.", "correct": false}, {"id": "b", "text": "lean, blades at superfine.", "correct": false}, {"id": "c", "text": "rich, blades at superfine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When unfeathering a propeller use', '[{"id": "a", "text": "minimum RPM/min throttle.", "correct": true}, {"id": "b", "text": "any RPM min throttle.", "correct": false}, {"id": "c", "text": "maximum RPM/min throttle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How is the concentricity of a propeller shaft checked?', '[{"id": "a", "text": "Micrometer.", "correct": false}, {"id": "b", "text": "Dial Test Indicator (DTI).", "correct": true}, {"id": "c", "text": "Ring gauge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller slip rings should be', '[{"id": "a", "text": "lubricated with silicon grease.", "correct": false}, {"id": "b", "text": "lubricated with graphite grease.", "correct": false}, {"id": "c", "text": "cleaned and left dry.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A splined hub is found be loose with the', '[{"id": "a", "text": "excessive spline wear.", "correct": false}, {"id": "b", "text": "front cones bottomed against the front end of the splines.", "correct": true}, {"id": "c", "text": "retaining nut torque loading too low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On propeller securing plates circlips should be', '[{"id": "a", "text": "annealed and the springiness put back into the circlip before it can be used again.", "correct": false}, {"id": "b", "text": "used once only.", "correct": true}, {"id": "c", "text": "used again as long as the circlip springs back first time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The cause of propeller out-of-track vibration is', '[{"id": "a", "text": "propeller blade angle too large.", "correct": false}, {"id": "b", "text": "static imbalance.", "correct": false}, {"id": "c", "text": "blade stiffness not exactly matched.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How is blending carried out on an aluminium propeller blade?', '[{"id": "a", "text": "By using a coarse file and peening.", "correct": false}, {"id": "b", "text": "By using a needle file and finish with emery cloth.", "correct": true}, {"id": "c", "text": "By using a scraper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If a 2 blade prop is placed on a knife edge and it ends up horizontal (blades at 3 and 9 o"clock positions), it is said to be in balance', '[{"id": "a", "text": "vertically.", "correct": false}, {"id": "b", "text": "horizontally.", "correct": true}, {"id": "c", "text": "dynamically.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following defects is cause for rejection of wooden propellers?', '[{"id": "a", "text": "An oversize hub or bolthole or elongated bolt holes.", "correct": true}, {"id": "b", "text": "No protective coating on propeller.", "correct": false}, {"id": "c", "text": "Solder missing from screw heads securing metal tipping.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Inspection of a propeller blade by dye penetrant inspection is accomplished to detect', '[{"id": "a", "text": "cracks.", "correct": true}, {"id": "b", "text": "corrosion at the blade tip.", "correct": false}, {"id": "c", "text": "torsional stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following is used to correct horizontal imbalance of a wooden propeller?', '[{"id": "a", "text": "Shellac.", "correct": false}, {"id": "b", "text": "Brass screws.", "correct": false}, {"id": "c", "text": "Solder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following determines oil and grease specifications for lubrication of propellers?', '[{"id": "a", "text": "Propeller manufacturers.", "correct": true}, {"id": "b", "text": "Engine Manufacturers.", "correct": false}, {"id": "c", "text": "Airframe manufacturers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What type of imbalance will cause a two-bladed propeller to have a persistent tendency to come to rest in a horizontal position (with the blades parallel to the ground) while being checked on a propeller balance beam?', '[{"id": "a", "text": "Harmonic.", "correct": false}, {"id": "b", "text": "Vertical.", "correct": true}, {"id": "c", "text": "Horizontal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What is the purpose of an arbor used in balancing a propeller?', '[{"id": "a", "text": "To support the propeller on the balance knives.", "correct": true}, {"id": "b", "text": "To mark the propeller blades where weights are to be be attached.", "correct": false}, {"id": "c", "text": "To level the balance stand.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'The application of more protective coating on one blade than another when refinishing a wood propeller', '[{"id": "a", "text": "has little or no effect on operating characteristics.", "correct": false}, {"id": "b", "text": "may be necessary to achieve final balancing.", "correct": true}, {"id": "c", "text": "should never be done.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Apparent engine roughness is often a result of propeller unbalance. The effect of an unbalanced propeller will usually be', '[{"id": "a", "text": "greater at high RPM.", "correct": true}, {"id": "b", "text": "greater at low RPM.", "correct": false}, {"id": "c", "text": "approximately the same at all speeds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller aerodynamic (thrust) imbalance can be largely eliminated by', '[{"id": "a", "text": "correct blade contouring and angle setting.", "correct": true}, {"id": "b", "text": "static balancing.", "correct": false}, {"id": "c", "text": "keeping the propeller blades within the same plane of rotation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propellers exposed to salt spray should be flushed with', '[{"id": "a", "text": "fresh water.", "correct": true}, {"id": "b", "text": "soapy water.", "correct": false}, {"id": "c", "text": "stoddard solvent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'How can a steel propeller hub be tested for cracks?', '[{"id": "a", "text": "By magnetic particle inspection.", "correct": true}, {"id": "b", "text": "By anodizing.", "correct": false}, {"id": "c", "text": "By etching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following defects is cause of rejection of a wood propeller?', '[{"id": "a", "text": "An oversize hub or bolt hole, or elongated bolt holes.", "correct": true}, {"id": "b", "text": "Solder missing from screw heads securing metal tipping.", "correct": false}, {"id": "c", "text": "No protective coating on propeller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Longitudinal (fore and aft) clearance of constant speed propeller blades or cuffs must be at least 1/2 inch (12.7 mm) between propeller parts and stationary parts of the aircraft. This clearance is with the propeller blades', '[{"id": "a", "text": "at the lowest pitch angle.", "correct": false}, {"id": "b", "text": "at take-off pitch (maximum thrust) angle.", "correct": false}, {"id": "c", "text": "feathered or in the most critical pitch configuration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When lubricating a Hartzell propeller blade with grease, to prevent damage to the blade seals, the service manual may recommend on some models to', '[{"id": "a", "text": "remove the seals prior to greasing and reinstall them afterwards.", "correct": false}, {"id": "b", "text": "remove one of the two grease nipples for the blade, and grease the blade throughh the", "correct": true}, {"id": "c", "text": "pump grease into both grease nipples for the blade simultaneously.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When running-up an engine and testing a newly installed hydromatic propeller, it is necessary to exercise the propeller by moving the governor control throughh its entire travel several times to', '[{"id": "a", "text": "remove any entrapped air.", "correct": true}, {"id": "b", "text": "test the maximum RPM setting of the governor.", "correct": false}, {"id": "c", "text": "seat the blades fully against the low pitch stop.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What is indicated when the front cone bottoms while installing a propeller?', '[{"id": "a", "text": "Blade angles are incorrect.", "correct": false}, {"id": "b", "text": "Propeller-dome combination is incorrect.", "correct": false}, {"id": "c", "text": "Rear cone should be moved forward.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'If the propeller cone or hub cone seats show evidence of galling and wear, the most likely cause is', '[{"id": "a", "text": "the propeller retaining nut was not tight enough during previous operation.", "correct": true}, {"id": "b", "text": "the front cone was not fully bottomed against the crankshaft splines during installation.", "correct": false}, {"id": "c", "text": "the pitch change stops were located incorrectly, causing the cone seats to act as the high pitch stop.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'On aircraft equiped with hydraulically operated constant speed propellers, all ignition and magneto checking is done with the propeller in which position?', '[{"id": "a", "text": "Low RPM.", "correct": false}, {"id": "b", "text": "High pitch range.", "correct": false}, {"id": "c", "text": "High RPM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Oil leakage around the rear cone of a hydromatic propeller usually indicates a defective', '[{"id": "a", "text": "spider-shaft oil seal.", "correct": true}, {"id": "b", "text": "piston gasket.", "correct": false}, {"id": "c", "text": "dome-barrel oil seal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Maximum taper contact between crankshaft and propeller hub is determined by using', '[{"id": "a", "text": "a micrometer.", "correct": false}, {"id": "b", "text": "a surface gauge.", "correct": false}, {"id": "c", "text": "bearing blue colour transfer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Propeller blade tracking is the process of determining', '[{"id": "a", "text": "the plane of rotation of the propeller with respect to the aircraft longitudinal axis.", "correct": false}, {"id": "b", "text": "that the blade angles are within specified tolerance of each other.", "correct": false}, {"id": "c", "text": "the positions of the tips of the propeller blades relative to each other.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'In what position is the constant-speed propeller control placed to check the magnetos?', '[{"id": "a", "text": "Full decrease, low propeller blade pitch angle.", "correct": false}, {"id": "b", "text": "Full increase, low propeller blade pitch angle.", "correct": true}, {"id": "c", "text": "Full increase, high propeller blade pitch angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Repairs of aluminium alloy adjustable pitch propellers are not permitted to be made on the', '[{"id": "a", "text": "face.", "correct": false}, {"id": "b", "text": "shank.", "correct": true}, {"id": "c", "text": "back.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following methods is used to straighten a bent aluminium propeller blade that is within repairable limits?', '[{"id": "a", "text": "Either hot or cold straightening, depending on the location and severity of damage.", "correct": false}, {"id": "b", "text": "Cold straightening only.", "correct": true}, {"id": "c", "text": "Careful heating to accomplish straightening, followed by heat treatment to store original strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'It is important that nicks in aluminium alloy propeller blades be repaired as soon as possible in order to', '[{"id": "a", "text": "maintain equal aerodynamic characteristics between blades.", "correct": false}, {"id": "b", "text": "eliminate stress concentration points.", "correct": true}, {"id": "c", "text": "equalize the centrifugal loads between the blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Minor surface damage located in a repairable area, but not on the leading or trailing edges of aluminium blades, may be repaired by first', '[{"id": "a", "text": "filing with a half round or flat file.", "correct": false}, {"id": "b", "text": "sanding and applying a proper filler.", "correct": false}, {"id": "c", "text": "filing with a riffle file.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Minor surface damage located in a repairable area, but not on the leading or trailing edges of composite blades, may be repaired by', '[{"id": "a", "text": "filing with a riffle file.", "correct": false}, {"id": "b", "text": "sanding and applying a proper filler.", "correct": true}, {"id": "c", "text": "filing with a half round or flat file.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'After removal of aluminium blade damage, the affected surface should be polished with', '[{"id": "a", "text": "fine steel wool.", "correct": false}, {"id": "b", "text": "very fine sandpaper.", "correct": true}, {"id": "c", "text": "powdered soapstone.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'When preparing a propeller blade for inspection it should be cleaned with', '[{"id": "a", "text": "mild soap and water.", "correct": true}, {"id": "b", "text": "steel wool.", "correct": false}, {"id": "c", "text": "methyl ethyl ketone.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'What method would you use to inspect an aluminium propeller blade when a crack is suspected?', '[{"id": "a", "text": "Dye penetrant inspection.", "correct": true}, {"id": "b", "text": "Magnetic particle inspection.", "correct": false}, {"id": "c", "text": "A bright light and magnifying glass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Removal of propeller blade tips within the Type Certificate Data Sheet limits to correct a defect is', '[{"id": "a", "text": "a major repair.", "correct": true}, {"id": "b", "text": "permitted under the privileges and limitations of a category B1 licence.", "correct": false}, {"id": "c", "text": "a major modification.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Which of the following generally renders an aluminium alloy propeller unrepairable?', '[{"id": "a", "text": "A transverse crack of any size.", "correct": true}, {"id": "b", "text": "Any slag inclusions or cold shuts.", "correct": false}, {"id": "c", "text": "Any repairs that would require shortening and re-contouring of blades.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'Rubber components should be stored in', '[{"id": "a", "text": "the dark.", "correct": true}, {"id": "b", "text": "natural light.", "correct": false}, {"id": "c", "text": "fluorescent light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M17.7'), 'A wooden propeller should be stored', '[{"id": "a", "text": "a dry and well ventilated area.", "correct": true}, {"id": "b", "text": "in a room with high humidity to stop it drying and cracking.", "correct": false}, {"id": "c", "text": "a warm but light storeroom.", "correct": false}]'::jsonb, '{B1,B2}');
